Lemma word_of_zpoly E Vz e z : L5K.zagree E Vz e -> L5KA.zpolyA Vz e = Some z -> edenot E e = Z_to_bv 64 z.
Proof. ltac2:(Rpl.RP.run_i (rplG ()) 4 "SD0|600;!1,;0!1+:1!2'=#3'>!2'<1#4!1+:#1!1+:#2%~R!3+5!1+:#3#2#1!3+5+2!2'A#4#3!2'A#4#2%~R!3+5+2!2'A#3#2!2'A#3#1!3+5!1+:#4#3#2!2'=#4'>!2'<19!2'C19!2'C1#4|10;!1,F=!1,F0!2'E>?!2'J,I>!1+S+2!2'^9#6#4$E;R+0$Vz;R%~R+1+2$e;R+3$z;R+2$A;R!3'4#4#3#2$Pz;R!3+5!1+6+2!2'7#4#3!2,8+2#2!6'92!2'<13$b;R2!3+52#14&H;R$n;R+?$b1;R5$b2;R6!5'@78%~R!3+5+2!2'A#3#2!2'A#3#1!3+5!1+:#4#3#2$~R7$~R%~R!3+5+2!2'A#4#3!2'A#4#2!3+5!1+:#5#4#3#1!3'B#3#2#1%n;R+?%b1;R5%b2;R68!4#11:4!6'9+2;$z;R+2!3+5+2#1!2'A1!2'<1#5!6'9+2<$z;R+2!3+5+2!2'C1!2'=#5'>#1vd!3'D#4@&__sat1;R!2'G>?%~R!2'H,I>%~R!2'J,I?!2'H,I@&__sat0;R$Ha;RA$~R+K!3'L>?#2%Ha;RA%~R+K!2'J,I@&__arith;R&__wit;R!1,M+N!1+O+N&__varmap;R!1,P+2!1+Q+2&__ff;R!6,RB'T+U+U,V!7,WB'T+U+U,V!4,X+2!3,Y+2!2,Z+2>1,[!2,Z+2,I,\!2'^0B,V!4'^1#1#3vv!2,^2+^3,^4!3+5+^3!2'^5#1#3,^4!3'^6+2,I#2%~R!3+5+2@,I+^7#1!3+5+2;<!2'A14!2'^81#4!2'A1:!2'^819C!3'^:C3!6'^;#6#5#4#3#2#1").
Qed.
(* [comment removed for export] *)
Lemma u64_of_KWord8a E M b off e a v a' : kentry_ok RSEGS E M (KWord (SA b off) 8 e) -> bv_unsigned (edenot E b) = a ->
  bv_unsigned (edenot E e) = v -> a' = a + off -> L5.u64_at RSEGS M a' v.
Proof. ltac2:(Rpl.RP.run_i (rplG ()) 8 "S20!1,;|600;|30;$E;R+0$M;R%~R!1+:0!1+6!1+:!1,;1$b;R+3$off;R+2$e;R+3$a;R+2$v;R+2$a';R+2$K;R!4'^<'^=#8#7!3,^>!2,^?#6#5}8#4$Ha;R!3+5+2!2'A0!2'^9#9#7#4$Hv;R!3+5+2!2'A0!2'^9#:#6#4$H;R!3+5+2#4!2'^@#6#8!6'9+2!2'^@#7#9$a';R+2!4'^A'^=#<#1#7!;'^B'^=#<#;#:#9#8#7#6#4#3#2#5#1").
Qed.
Lemma u32_of_KWord4a E M b off e a v a' : kentry_ok RSEGS E M (KWord (SA b off) 4 e) -> bv_unsigned (edenot E b) = a ->
  bv_unsigned (edenot E e) = v -> a' = a + off -> L5.u32_at RSEGS M a' v.
Proof. ltac2:(Rpl.RP.run_i (rplG ()) 8 "S20!1,;|600;|30;$E;R+0$M;R%~R!1+:0!1+6!1+:!1,;1$b;R+3$off;R+2$e;R+3$a;R+2$v;R+2$a';R+2$K;R!4'^<'^=#8#7!3,^>!2,^?#6#5}4#4$Ha;R!3+5+2!2'A0!2'^9#9#7#4$Hv;R!3+5+2!2'A0!2'^9#:#6#4$H;R!3+5+2#4!2'^@#6#8!6'9+2!2'^@#7#9$a';R+2!4'^C'^=#<#1#7!;'^D'^=#<#;#:#9#8#7#6#4#3#2#5#1").
Qed.
Lemma u8_of_KWord1a E M b off e a v a' : kentry_ok RSEGS E M (KWord (SA b off) 1 e) -> bv_unsigned (edenot E b) = a ->
  bv_unsigned (edenot E e) = v -> 0 <= v < 256 -> a' = a + off -> L5.u8_at RSEGS M a' v.
Proof. ltac2:(Rpl.RP.run_i (rplG ()) 8 "S30|600;!1,;0|30;$E;R+0$M;R%~R!1+:1!1+6!1+:!1,;2$b;R+3$off;R+2$e;R+3$a;R+2$v;R+2$a';R+2$K;R!4'^<'^=#8#7!3,^>!2,^?#6#5}1#4$Ha;R!3+5+2!2'A1!2'^9#9#7#4$Hv;R!3+5+2!2'A1!2'^9#:#6#4$Hr;R!2+^E!2'J,I#5!2'H#5!1,F|800;$H;R!3+5+2#5!2'^@#7#9!6'9+2!2'^@#8#:$a';R+2!4'^F'^=#=#1#8!<'^G'^=#=#<#;#:#9#8#7#5#4#3#2#6#1").
Qed.
Lemma defined_of_KUnka E M b off ne a n a' : kentry_ok RSEGS E M (KUnk (SA b off) ne) -> bv_unsigned (edenot E b) = a ->
  bv_unsigned (edenot E ne) = n -> a' = a + off -> L5.defined M a' n.
